<?php
declare(strict_types=1);
require_once __DIR__ . '/../PRACTICAL-10/session.php';
$user=sh_auth_user();
if($user===null){header('Location: ../PRACTICAL-02/login.php'.(!empty($_SESSION['session_expired'])?'?expired=1':''));exit;}
if(($user['role']??'')!=='admin'){header('Location: ../PRACTICAL-02/dashboard.php');exit;}
$csrf=sh_csrf_token();$db=studentHubMysqli();$errors=[];$notice='';
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$uploadDir=__DIR__.'/uploads';if(!is_dir($uploadDir)&&!mkdir($uploadDir,0755,true)&&!is_dir($uploadDir))$errors[]='The poster upload folder could not be created.';
function p12_bind(mysqli_stmt $s,string $types,array $values):void{if($types==='')return;$refs=[];foreach($values as $k=>&$v)$refs[$k]=&$v;$s->bind_param($types,...$refs);}
function p12_audit(mysqli $db,int $adminId,?int $eventId,string $action):void{$s=$db->prepare('INSERT INTO event_management_audit (admin_user_id,event_id,event_type) VALUES (?,?,?)');$s->bind_param('iis',$adminId,$eventId,$action);$s->execute();$s->close();}
if(isset($_GET['notice'])){$messages=['created'=>'Event added successfully.','updated'=>'Event updated successfully.','deleted'=>'Event deleted successfully.'];$notice=$messages[(string)$_GET['notice']]??'';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 if(!sh_valid_csrf($_POST['csrf_token']??null))$errors[]='Your session could not verify this request. Refresh and try again.';
 else try{
  if($action==='save'){
   $id=filter_var($_POST['event_id']??null,FILTER_VALIDATE_INT)?:0;$title=trim((string)($_POST['title']??''));$category=trim((string)($_POST['category']??''));$date=trim((string)($_POST['event_date']??''));$date=$date===''?null:$date;$venue=trim((string)($_POST['venue']??''));$description=trim((string)($_POST['description']??''));$status=(string)($_POST['status']??'open');
   if($title===''||mb_strlen($title)>150)$errors[]='Enter an event title (up to 150 characters).';if($category===''||mb_strlen($category)>60)$errors[]='Enter a category (up to 60 characters).';
   if($date!==null&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$errors[]='Choose a valid event date.';if($venue===''||mb_strlen($venue)>150)$errors[]='Enter a venue (up to 150 characters).';if($description==='')$errors[]='Enter an event description.';if(!in_array($status,['open','closed'],true))$errors[]='Choose open or closed status.';
   $existing=null;if($id>0){$f=$db->prepare('SELECT poster_path FROM events WHERE event_id=?');$f->bind_param('i',$id);$f->execute();$existing=$f->get_result()->fetch_assoc();$f->close();if(!$existing)$errors[]='The event being edited no longer exists.';}
   $oldPoster=$existing['poster_path']??null;$newPoster=isset($_POST['remove_poster'])&&$_POST['remove_poster']==='1'?null:$oldPoster;$newPath=null;$file=$_FILES['poster']??null;
   if($file&&(int)$file['error']!==UPLOAD_ERR_NO_FILE){if((int)$file['error']!==UPLOAD_ERR_OK)$errors[]='The poster upload did not complete. Check the file and try again.';elseif((int)$file['size']>2*1024*1024)$errors[]='Poster must be no larger than 2 MB.';elseif(!is_uploaded_file((string)$file['tmp_name']))$errors[]='The uploaded poster could not be verified.';else{$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file((string)$file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$errors[]='Poster must be a JPEG, PNG, or WebP image.';else{$newPoster=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$newPath=$uploadDir.'/'.$newPoster;}}}
   if(!$errors){if($newPath!==null&&!move_uploaded_file((string)$file['tmp_name'],$newPath))$errors[]='The poster could not be saved. Check upload folder permissions.';else try{
    $db->begin_transaction();
    if($id>0){$s=$db->prepare('UPDATE events SET title=?,category=?,event_date=?,venue=?,description=?,status=?,poster_path=? WHERE event_id=?');$s->bind_param('sssssssi',$title,$category,$date,$venue,$description,$status,$newPoster,$id);$s->execute();$s->close();p12_audit($db,(int)$user['user_id'],$id,'updated');$db->commit();if($oldPoster&&$oldPoster!==$newPoster&&is_file($uploadDir.'/'.$oldPoster))@unlink($uploadDir.'/'.$oldPoster);header('Location: events.php?notice=updated');exit;}
    $s=$db->prepare('INSERT INTO events (title,category,event_date,venue,description,status,poster_path) VALUES (?,?,?,?,?,?,?)');$s->bind_param('sssssss',$title,$category,$date,$venue,$description,$status,$newPoster);$s->execute();$eventId=(int)$s->insert_id;$s->close();p12_audit($db,(int)$user['user_id'],$eventId,'created');$db->commit();header('Location: events.php?notice=created');exit;
   }catch(Throwable $x){$db->rollback();if($newPath&&is_file($newPath))@unlink($newPath);throw $x;}}
  }elseif($action==='delete'){$id=filter_var($_POST['event_id']??null,FILTER_VALIDATE_INT)?:0;if($id<1)$errors[]='Choose a valid event.';else{$f=$db->prepare('SELECT poster_path FROM events WHERE event_id=?');$f->bind_param('i',$id);$f->execute();$event=$f->get_result()->fetch_assoc();$f->close();if(!$event)$errors[]='The event was already removed.';else{$db->begin_transaction();try{$poster=$event['poster_path'];p12_audit($db,(int)$user['user_id'],$id,'deleted');$s=$db->prepare('DELETE FROM events WHERE event_id=?');$s->bind_param('i',$id);$s->execute();$s->close();$db->commit();if($poster&&is_file($uploadDir.'/'.$poster))@unlink($uploadDir.'/'.$poster);header('Location: events.php?notice=deleted');exit;}catch(Throwable $x){$db->rollback();throw $x;}}}}
  else $errors[]='Choose a valid event action.';
 }catch(Throwable $x){error_log('Practical 12 event management: '.$x->getMessage());if(!$errors&&(int)$x->getCode()===1451)$errors[]='This event has registrations and cannot be deleted while those registrations exist.';elseif(!$errors)$errors[]='The database could not complete this request. Check MySQL and import the Practical 12 SQL migration.';}
}
$q=trim((string)($_GET['q']??''));$categoryFilter=trim((string)($_GET['category']??''));$statusFilter=in_array($_GET['status']??'',['open','closed'],true)?(string)$_GET['status']:'';$page=max(1,(int)($_GET['page']??1));$perPage=8;
$where=[];$types='';$params=[];if($q!==''){$where[]='(title LIKE ? OR venue LIKE ? OR description LIKE ?)';$like='%'.$q.'%';$types.='sss';array_push($params,$like,$like,$like);}if($categoryFilter!==''){$where[]='category=?';$types.='s';$params[]=$categoryFilter;}if($statusFilter!==''){$where[]='status=?';$types.='s';$params[]=$statusFilter;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$events=[];$categories=[];$editEvent=null;$totalPages=1;
try{$r=$db->query('SELECT DISTINCT category FROM events ORDER BY category');while($row=$r->fetch_assoc())$categories[]=$row['category'];if(isset($_GET['edit'])){$editId=filter_var($_GET['edit'],FILTER_VALIDATE_INT)?:0;if($editId>0){$s=$db->prepare('SELECT event_id,title,category,event_date,venue,description,status,poster_path FROM events WHERE event_id=?');$s->bind_param('i',$editId);$s->execute();$editEvent=$s->get_result()->fetch_assoc()?:null;$s->close();}}
 $s=$db->prepare('SELECT COUNT(*) AS total FROM events'.$whereSql);p12_bind($s,$types,$params);$s->execute();$total=(int)$s->get_result()->fetch_assoc()['total'];$s->close();$totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);$offset=($page-1)*$perPage;
 $s=$db->prepare('SELECT event_id,title,category,event_date,venue,description,status,poster_path FROM events'.$whereSql.' ORDER BY event_date IS NULL,event_date DESC,event_id DESC LIMIT ?,?');p12_bind($s,$types.'ii',[...$params,$offset,$perPage]);$s->execute();$r=$s->get_result();while($row=$r->fetch_assoc())$events[]=$row;$s->close();
}catch(mysqli_sql_exception $x){error_log('Practical 12 event list: '.$x->getMessage());$errors[]='Events could not be loaded. Import the Practical 12 SQL file and ensure MySQL is running.';}
$editId=(int)($_POST['event_id']??$editEvent['event_id']??0);$fv=static fn(string $key,string $default=''):string=>(string)($_POST[$key]??$editEvent[$key]??$default);
function p12_url(array $replace=[]):string{return 'events.php?'.http_build_query(array_merge($_GET,$replace));}
